28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    @Email
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "membership_number")
85	    private String membershipNumber;
86	
87	    @Column(name = "bulk_signup_warning")
88	    private Boolean bulkSignupWarning;
89	
90	    @Column(name = "household_size")
91	    private Integer householdSize;
92	
93	    @Column(name = "possible_duplicate")
94	    private Boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @Column(name = "deleted", nullable = false)
100	    private Boolean deleted = false;
101	
102	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
103	    private Set<Pet> pets;
104	
105	    public String getTitle() {
106	        return this.title;
107	    }
108	
109	    public void setTitle(String title) {
110	        this.title = title;
111	    }
112	
113	    /**
114	     * The owner's salutation, composed from its {@link #getTitle() title} and
115	     * {@link #getLastName() last name}: {@code title + ' ' + lastName} when a title is
116	     * present, or just the last name when no title was supplied. Derived (not persisted);
117	     * recomputed each call. See {@link OwnerDerivations#salutation(String, String)}.
118	     *
119	     * @return the composed salutation
120	     */
121	    @Transient
122	    public String getSalutation() {
123	        return OwnerDerivations.salutation(this.title, this.getLastName());
124	    }
125	
126	    public String getAddress() {
127	        return this.address;
128	    }
129	
130	    public void setAddress(String address) {
131	        this.address = address;
132	    }
133	
134	    public String getAddressLine1() {
135	        return this.addressLine1;
136	    }
137	
138	    public void setAddressLine1(String addressLine1) {
139	        this.addressLine1 = addressLine1;
140	    }
141	
142	    public String getAddressLine2() {
143	        return this.addressLine2;
144	    }
145	
146	    public void setAddressLine2(String addressLine2) {
147	        this.addressLine2 = addressLine2;
148	    }
149	
150	    public String getCity() {
151	        return this.city;
152	    }
153	
154	    public void setCity(String city) {
155	        this.city = city;
156	    }
157	
158	    /**
159	     * The owner's locality, i.e. the canonical region it belongs to (read from the
160	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
161	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
162	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
163	     * full derivation.
164	     *
165	     * @return the canonical region string, or {@code "UNKNOWN"}
166	     */
167	    @Transient
168	    public String getLocality() {
169	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
170	    }
171	
172	    /**
173	     * The canonical region derived for this owner from its own fields. Recomputed each
174	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
175	     *
176	     * @return the canonical region string, or {@code "UNKNOWN"}
177	     */
178	    public String regionForOwner() {
179	        return OwnerDerivations.region(this.postcode, this.city);
180	    }
181	
182	    /**
183	     * The owner's IANA timezone name, derived from its {@link #getLocality() locality}
184	     * (canonical region) via the fixed region-to-timezone table. Derived (not persisted);
185	     * recomputed each call and {@code null} when the locality is not a known region. See
186	     * {@link OwnerDerivations#timezone(String)} for the derivation.
187	     *
188	     * @return the IANA timezone name, or {@code null}
189	     */
190	    @Transient
191	    public String getTimezone() {
192	        return OwnerDerivations.timezone(this.getLocality());
193	    }
194	
195	    /**
196	     * Whether this owner's postcode is consistent with its {@link #getLocality()
197	     * locality}: an absent postcode is accepted, a present one must be exactly four
198	     * digits and, when the locality has a known postcode range, fall within it. See
199	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
200	     *
201	     * @return {@code true} if the postcode is absent or valid for the owner's locality
202	     */
203	    public boolean postcodeValidForLocality() {
204	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
205	    }
206	
207	    /**
208	     * The owner's membership points, a non-negative score derived from its factors.
209	     * Derived (not persisted); recomputed from the current fields each call, so it rises
210	     * once the owner's tenure since {@link #registrationDate} exceeds 365 days. See
211	     * {@link OwnerDerivations#membershipPoints(String, Integer, Integer, LocalDate, LocalDate)}
212	     * for how it is scored.
213	     *
214	     * @return the membership points, 0 or more
215	     */
216	    @Transient
217	    public Integer getMembershipPoints() {
218	        return OwnerDerivations.membershipPoints(this.email, this.namesakeCount, this.householdSize,
219	            this.registrationDate, LocalDate.now());
220	    }
221	
222	    /**
223	     * The owner's membership level, a number from 1 to 4, mapped from its
224	     * {@link #getMembershipPoints() membership points}. Derived (not persisted);
225	     * recomputed from the current fields each call, so it rises to level 4 once the
226	     * owner's tenure since {@link #registrationDate} exceeds 365 days. See
227	     * {@link OwnerDerivations#membershipLevel(int)} for the mapping.
228	     *
229	     * @return the membership level, from 1 to 4
230	     */
231	    @Transient
232	    public Integer getMembershipLevel() {
233	        return OwnerDerivations.membershipLevel(getMembershipPoints());
234	    }
235	
236	    /**
237	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
238	     * Derived (not persisted); recomputed from the current fields each call. See
239	     * {@link OwnerDerivations#contactPreference(String)}.
240	     *
241	     * @return {@code "EMAIL"} or {@code "PHONE"}
242	     */
243	    @Transient
244	    public String getContactPreference() {
245	        return OwnerDerivations.contactPreference(this.email);
246	    }
247	
248	    public String getTelephone() {
249	        return this.telephone;
250	    }
251	
252	    /**
253	     * The stored E.164 {@link #telephone} formatted for humans: a leading '+'
254	     * and country code, a space, then the national digits grouped in threes
255	     * (e.g. {@code "+61 412 345 678"}). Derived (not persisted); recomputed each
256	     * call and {@code null} when no telephone is present. See
257	     * {@link Telephones#toDisplay(String)} for the exact format.
258	     *
259	     * @return the human-formatted telephone, or {@code null} when absent
260	     */
261	    @Transient
262	    public String getTelephoneDisplay() {
263	        return Telephones.toDisplay(this.telephone);
264	    }
265	
266	    public void setTelephone(String telephone) {
267	        this.telephone = telephone;
268	    }
269	
270	    public String getEmail() {
271	        return this.email;
272	    }
273	
274	    public void setEmail(String email) {
275	        this.email = email;
276	    }
277	
278	    public String getPostcode() {
279	        return this.postcode;
280	    }
281	
282	    public void setPostcode(String postcode) {
283	        this.postcode = postcode;
284	    }
285	
286	    public LocalDate getRegistrationDate() {
287	        return this.registrationDate;
288	    }
289	
290	    public void setRegistrationDate(LocalDate registrationDate) {
291	        this.registrationDate = registrationDate;
292	    }
293	
294	    public LocalDate getBirthDate() {
295	        return this.birthDate;
296	    }
297	
298	    public void setBirthDate(LocalDate birthDate) {
299	        this.birthDate = birthDate;
300	    }
301	
302	    /**
303	     * The owner's age band, {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"},
304	     * derived from {@link #birthDate} measured against {@link #registrationDate}.
305	     * Derived (not persisted); recomputed each call and {@code null} when no birth
306	     * date has been supplied. See
307	     * {@link OwnerDerivations#ageBand(LocalDate, LocalDate)} for the derivation.
308	     *
309	     * @return the age band, or {@code null} when no birth date is present
310	     */
311	    @Transient
312	    public String getAgeBand() {
313	        return OwnerDerivations.ageBand(this.birthDate, this.registrationDate);
314	    }
315	
316	    /**
317	     * The owner's fiscal year, formatted {@code FY<YY>}, derived from its
318	     * business-day-adjusted {@link #registrationDate} (the fiscal year starts on 1 July).
319	     * Derived (not persisted); recomputed each call and {@code null} when no registration
320	     * date is present. See {@link OwnerDerivations#fiscalYear(LocalDate)} for the derivation.
321	     *
322	     * @return the fiscal year as {@code FY<YY>}, or {@code null}
323	     */
324	    @Transient
325	    public String getFiscalYear() {
326	        return OwnerDerivations.fiscalYear(this.registrationDate);
327	    }
328	
329	    public String getCustomerCode() {
330	        return this.customerCode;
331	    }
332	
333	    public void setCustomerCode(String customerCode) {
334	        this.customerCode = customerCode;
335	    }
336	
337	    /**
338	     * The Luhn check digit (0-9) computed over the digits in this owner's
339	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
340	     * {@link OwnerDerivations#checkDigit(String)}.
341	     *
342	     * @return the Luhn check digit, from 0 to 9
343	     */
344	    @Transient
345	    public Integer getCheckDigit() {
346	        return OwnerDerivations.checkDigit(this.customerCode);
347	    }
348	
349	    public String getHouseholdId() {
350	        return this.householdId;
351	    }
352	
353	    public void setHouseholdId(String householdId) {
354	        this.householdId = householdId;
355	    }
356	
357	    public Integer getNamesakeCount() {
358	        return this.namesakeCount;
359	    }
360	
361	    public void setNamesakeCount(Integer namesakeCount) {
362	        this.namesakeCount = namesakeCount;
363	    }
364	
365	    public String getMembershipNumber() {
366	        return this.membershipNumber;
367	    }
368	
369	    public void setMembershipNumber(String membershipNumber) {
370	        this.membershipNumber = membershipNumber;
371	    }
372	
373	    public Boolean getBulkSignupWarning() {
374	        return this.bulkSignupWarning;
375	    }
376	
377	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
378	        this.bulkSignupWarning = bulkSignupWarning;
379	    }
380	
381	    public Integer getHouseholdSize() {
382	        return this.householdSize;
383	    }
384	
385	    public void setHouseholdSize(Integer householdSize) {
386	        this.householdSize = householdSize;
387	    }
388	
389	    public Boolean getPossibleDuplicate() {
390	        return this.possibleDuplicate;
391	    }
392	
393	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
394	        this.possibleDuplicate = possibleDuplicate;
395	    }
396	
397	    public Integer getPossibleDuplicateOf() {
398	        return this.possibleDuplicateOf;
399	    }
400	
401	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
402	        this.possibleDuplicateOf = possibleDuplicateOf;
403	    }
404	
405	    public Boolean getDeleted() {
406	        return this.deleted;
407	    }
408	
409	    public void setDeleted(Boolean deleted) {
410	        this.deleted = deleted;
411	    }
412	
413	    /**
414	     * The derived key used for duplicate detection, combining this owner's normalised
415	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
416	     * their whole identity keys are equal, so members of the same household with
417	     * different telephones have different keys. Derived (not persisted); recomputed each
418	     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
419	     * exact format.
420	     *
421	     * @return the owner's identity key
422	     */
423	    @Transient
424	    public String getIdentityKey() {
425	        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
426	    }
427	
428	    /**
429	     * Compute the customer code to assign to this owner at creation, formatted
430	     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
431	     * value stored in {@link #getCustomerCode()}; see
432	     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
433	     *
434	     * @return the customer code to assign
435	     */
436	    public String computeCustomerCode() {
437	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
438	    }
439	
440	    /**
441	     * Compute the membership number to assign to this owner at creation, formatted
442	     * {@code <customerCode>-M<YY>} from its already-assigned customer code and registration
443	     * date. This is the value stored in {@link #getMembershipNumber()}; see
444	     * {@link OwnerDerivations#membershipNumber(String, LocalDate)} for the exact format.
445	     *
446	     * @return the membership number to assign
447	     */
448	    public String computeMembershipNumber() {
449	        return OwnerDerivations.membershipNumber(this.customerCode, this.registrationDate);
450	    }
451	
452	    /**
453	     * Compute the stable household identifier for this owner, derived deterministically
454	     * from its last name and postcode so every owner sharing a last name and postcode
455	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
456	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
457	     *
458	     * @return the household identifier
459	     */
460	    public String computeHouseholdId() {
461	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
462	    }
463	
464	    /**
465	     * Whether this owner belongs to the same household as {@code other}: that is, they
466	     * share the same last name and postcode. The last name is compared
467	     * case-insensitively with runs of whitespace collapsed to a single space (and
468	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
469	     * absent postcodes count as equal). Owners in the same household resolve to the same
470	     * {@link #computeHouseholdId() household identifier}.
471	     *
472	     * @param other the owner to compare against
473	     * @return {@code true} if both owners share a household
474	     */
475	    public boolean sameHouseholdAs(Owner other) {
476	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
477	            && Objects.equals(this.postcode, other.postcode);
478	    }
479	
480	    /**
481	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
482	     * trim, collapse internal runs of whitespace to a single space and lower-case.
483	     */
484	    private static String normalize(String value) {
485	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
486	    }
487	
488	    /**
489	     * Reduce an address to its canonical stored form. This is the value stored,
490	     * returned and used for every household comparison; see
491	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
492	     *
493	     * @param value the raw address (may be {@code null})
494	     * @return the normalised address, or the empty string if {@code value} is
495	     *         {@code null} or blank
496	     */
497	    public static String normalizeAddress(String value) {
498	        return OwnerDerivations.normalizeAddress(value);
499	    }
500	
501	    protected Set<Pet> getPetsInternal() {
502	        if (this.pets == null) {
503	            this.pets = new HashSet<>();
504	        }
505	        return this.pets;
506	    }
507	
508	    protected void setPetsInternal(Set<Pet> pets) {
509	        this.pets = pets;
510	    }
511	
512	    public List<Pet> getPets() {
513	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
514	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
515	        return Collections.unmodifiableList(sortedPets);
516	    }
517	
518	    public void setPets(List<Pet> pets) {
519	        this.pets = new HashSet<>(pets);
520	    }
521	
522	    public void addPet(Pet pet) {
523	        getPetsInternal().add(pet);
524	        pet.setOwner(this);
525	    }
526	
527	    /**
528	     * Return the Pet with the given name, or null if none found for this Owner.
529	     *
530	     * @param name to test
531	     * @return true if pet name is already in use
532	     */
533	    public Pet getPet(String name) {
534	        return getPet(name, false);
535	    }
536	
537	    /**
538	     * Return the Pet with the given name, or null if none found for this Owner.
539	     *
540	     * @param name to test
541	     * @return true if pet name is already in use
542	     */
543	    public Pet getPet(String name, boolean ignoreNew) {
544	        name = name.toLowerCase();
545	        for (Pet pet : getPetsInternal()) {
546	            if (!ignoreNew || !pet.isNew()) {
547	                String compName = pet.getName();
548	                compName = compName.toLowerCase();
549	                if (compName.equals(name)) {
550	                    return pet;
551	                }
552	            }
553	        }
554	        return null;
555	    }
556	
557	    public Pet getPet(Integer petId) {
558	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
559	    }
560	
561	    @Override
562	    public String toString() {
563	        return new ToStringCreator(this)
564	
565	            .append("id", this.getId())
566	            .append("new", this.isNew())
567	            .append("lastName", this.getLastName())
568	            .append("firstName", this.getFirstName())
569	            .append("address", this.address)
570	            .append("city", this.city)
571	            .append("telephone", this.telephone)
572	            .toString();
573	    }
574	}
