16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Month;
23	import java.time.Period;
24	import java.util.Map;
25	
26	/**
27	 * Pure derivations of an {@link Owner}'s read-only attributes.
28	 *
29	 * <p>Each method computes one derived value from an owner's own field values and
30	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
31	 * exposes these through thin {@code @Transient} getters that pass in the relevant
32	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
33	 * to describe its persistent state and relationships while its growing family of
34	 * derived attributes lives together in one place.
35	 */
36	final class OwnerDerivations {
37	
38	    /** Fixed city-to-region table used to derive {@link #region}. */
39	    private static final Map<String, String> CITY_REGION = Map.of(
40	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
41	
42	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
43	     *  {@link #region} in preference to the city. */
44	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
45	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
46	
47	    /** Fixed region-to-timezone table (IANA names) used to derive {@link #timezone}. */
48	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
49	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
50	
51	    private OwnerDerivations() {
52	    }
53	
54	    /**
55	     * The owner's locality, i.e. the canonical region it belongs to. This is read
56	     * from the region-and-hash {@code customerCode} identity: the region is the
57	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
58	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
59	     * been assigned a customer code (for example while its create request is still
60	     * being validated) this falls back to the region derived directly from its own
61	     * fields (see {@link #region(String, String)}).
62	     *
63	     * @return the canonical region string, or {@code "UNKNOWN"}
64	     */
65	    static String locality(String customerCode, String postcode, String city) {
66	        if (customerCode != null) {
67	            int dash = customerCode.indexOf('-');
68	            if (dash >= 0) {
69	                return customerCode.substring(0, dash);
70	            }
71	        }
72	        return region(postcode, city);
73	    }
74	
75	    /**
76	     * The canonical region derived for an owner from its own fields. The postcode is
77	     * consulted first: when it is present and falls within a known region's inclusive
78	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
79	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
80	     * known range does this fall back to the fixed city-to-region table
81	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
82	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
83	     * the same region for the known cities while disambiguating cities that share a name
84	     * via their postcode.
85	     *
86	     * @return the canonical region string, or {@code "UNKNOWN"}
87	     */
88	    static String region(String postcode, String city) {
89	        String byPostcode = regionForPostcode(postcode);
90	        if (byPostcode != null) {
91	            return byPostcode;
92	        }
93	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
94	    }
95	
96	    /**
97	     * The IANA timezone name derived from the given {@code locality} (a canonical
98	     * region) via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
99	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
100	     * {@code null} when the locality is not one of the known regions (for example
101	     * {@code "UNKNOWN"}).
102	     *
103	     * @return the IANA timezone name, or {@code null}
104	     */
105	    static String timezone(String locality) {
106	        return REGION_TIMEZONE.get(locality);
107	    }
108	
109	    /**
110	     * The region whose inclusive postcode range contains the given postcode, or
111	     * {@code null} when the postcode is absent, not a four-digit number, or in no
112	     * known range.
113	     */
114	    private static String regionForPostcode(String postcode) {
115	        if (postcode == null || !postcode.matches("\\d{4}")) {
116	            return null;
117	        }
118	        int value = Integer.parseInt(postcode);
119	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
120	            int[] range = entry.getValue();
121	            if (value >= range[0] && value <= range[1]) {
122	                return entry.getKey();
123	            }
124	        }
125	        return null;
126	    }
127	
128	    /**
129	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
130	     * absent postcode is always accepted, a present postcode must be exactly four
131	     * digits and, when the region has a known inclusive postcode range
132	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
133	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
134	     * four-digit postcode.
135	     *
136	     * @return {@code true} if the postcode is absent or valid for the region
137	     */
138	    static boolean postcodeMatchesRegion(String postcode, String region) {
139	        if (postcode == null) {
140	            return true;
141	        }
142	        if (!postcode.matches("\\d{4}")) {
143	            return false;
144	        }
145	        int[] range = REGION_POSTCODES.get(region);
146	        if (range == null) {
147	            return true;
148	        }
149	        int value = Integer.parseInt(postcode);
150	        return value >= range[0] && value <= range[1];
151	    }
152	
153	    /**
154	     * The owner's membership points, a non-negative score derived from its factors:
155	     * starting at 0, add 2 when an {@code email} is present, add 1 when
156	     * {@code namesakeCount} is 0, add 2 for a household of 3 or more (its
157	     * {@code householdSize}) and add 3 when the owner's tenure exceeds a year, measured as
158	     * the number of whole fiscal years elapsed from its {@code registrationDate} up to
159	     * {@code asOf} (the fiscal year starts on 1 July). Because a newly created owner has
160	     * zero elapsed fiscal years, it never earns the tenure points at creation.
161	     *
162	     * @return the membership points, 0 or more
163	     */
164	    static int membershipPoints(String email, Integer namesakeCount, Integer householdSize,
165	            LocalDate registrationDate, LocalDate asOf) {
166	        int points = 0;
167	        if (hasEmail(email)) {
168	            points += 2;
169	        }
170	        if (namesakeCount != null && namesakeCount == 0) {
171	            points += 1;
172	        }
173	        if (householdSize != null && householdSize >= 3) {
174	            points += 2;
175	        }
176	        if (tenureExceedsYear(registrationDate, asOf)) {
177	            points += 3;
178	        }
179	        return points;
180	    }
181	
182	    /**
183	     * The owner's membership level, a number from 1 to 4, mapped from its
184	     * {@link #membershipPoints(String, Integer, Integer, LocalDate, LocalDate) membership
185	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5 and level 4 for 6
186	     * or more.
187	     *
188	     * @return the membership level, from 1 to 4
189	     */
190	    static int membershipLevel(int points) {
191	        if (points <= 1) {
192	            return 1;
193	        }
194	        if (points <= 3) {
195	            return 2;
196	        }
197	        if (points <= 5) {
198	            return 3;
199	        }
200	        return 4;
201	    }
202	
203	    /**
204	     * Whether the owner's tenure exceeds a year, i.e. at least one whole fiscal year has
205	     * elapsed from its {@code registrationDate} up to {@code asOf} (see
206	     * {@link #elapsedFiscalYears(LocalDate, LocalDate)}). This is the single tenure test
207	     * the tenure-driven membership derivations share, so they agree on exactly when an
208	     * owner has been a member for "over a year"; it is {@code false} whenever either date
209	     * is absent.
210	     */
211	    private static boolean tenureExceedsYear(LocalDate registrationDate, LocalDate asOf) {
212	        return registrationDate != null && asOf != null
213	            && elapsedFiscalYears(registrationDate, asOf) >= 1;
214	    }
215	
216	    /**
217	     * The number of whole fiscal years elapsed from {@code registrationDate} up to
218	     * {@code asOf}, i.e. the difference between the fiscal year that contains {@code asOf}
219	     * and the one that contains {@code registrationDate} (see {@link #fiscalYearOf(LocalDate)}).
220	     * Two dates in the same fiscal year yield {@code 0}, so an owner registered in the
221	     * current fiscal year has zero tenure until the next 1 July rollover.
222	     */
223	    static int elapsedFiscalYears(LocalDate registrationDate, LocalDate asOf) {
224	        return fiscalYearOf(asOf) - fiscalYearOf(registrationDate);
225	    }
226	
227	    /**
228	     * The fiscal year that contains the given date, as a four-digit calendar year. The
229	     * fiscal year runs from 1 July to 30 June and is labelled by the calendar year in
230	     * which it ends: a date from January to June falls in the fiscal year of its own
231	     * calendar year, while a date from July to December falls in the next calendar year's
232	     * fiscal year (e.g. {@code 2026-05-03 -> 2026} but {@code 2026-08-03 -> 2027}).
233	     */
234	    static int fiscalYearOf(LocalDate date) {
235	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
236	    }
237	
238	    /**
239	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of
240	     * the fiscal year (see {@link #fiscalYearOf(LocalDate)}) that contains its
241	     * business-day-adjusted {@code registrationDate}, e.g. {@code FY27} for a registration
242	     * date of {@code 2026-08-03}. Returns {@code null} when no registration date is present.
243	     *
244	     * @return the fiscal year as {@code FY<YY>}, or {@code null}
245	     */
246	    static String fiscalYear(LocalDate registrationDate) {
247	        if (registrationDate == null) {
248	            return null;
249	        }
250	        return String.format("FY%02d", fiscalYearOf(registrationDate) % 100);
251	    }
252	
253	    /**
254	     * The owner's salutation, formed as {@code title + ' ' + lastName} when a
255	     * {@code title} is present, or just the {@code lastName} when no title is supplied.
256	     * A {@code null} or blank title contributes nothing, yielding the bare last name.
257	     *
258	     * @return the composed salutation
259	     */
260	    static String salutation(String title, String lastName) {
261	        if (title == null || title.isBlank()) {
262	            return lastName;
263	        }
264	        return title + " " + lastName;
265	    }
266	
267	    /**
268	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
269	     * is present, otherwise {@code "PHONE"}.
270	     *
271	     * @return {@code "EMAIL"} or {@code "PHONE"}
272	     */
273	    static String contactPreference(String email) {
274	        if (hasEmail(email)) {
275	            return "EMAIL";
276	        }
277	        return "PHONE";
278	    }
279	
280	    /**
281	     * Whether the owner has an email address on file, i.e. its {@code email} is present
282	     * and not blank. This is the single presence test the email-driven derivations share
283	     * (a membership-level factor and the {@link #contactPreference(String) contact
284	     * preference}), so they agree on exactly what counts as "has an email".
285	     */
286	    private static boolean hasEmail(String email) {
287	        return email != null && !email.isBlank();
288	    }
289	
290	    /**
291	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
292	     * given {@code customerCode}, processed right-to-left with every second digit
293	     * doubled (and reduced by 9 when the double exceeds 9). Non-digit characters are
294	     * ignored, and an absent or digit-free customer code yields {@code 0}.
295	     *
296	     * @return the Luhn check digit, from 0 to 9
297	     */
298	    static int checkDigit(String customerCode) {
299	        int sum = 0;
300	        boolean doubleDigit = true;
301	        for (int i = (customerCode == null ? 0 : customerCode.length()) - 1; i >= 0; i--) {
302	            char c = customerCode.charAt(i);
303	            if (c < '0' || c > '9') {
304	                continue;
305	            }
306	            int d = c - '0';
307	            if (doubleDigit) {
308	                d *= 2;
309	                if (d > 9) {
310	                    d -= 9;
311	                }
312	            }
313	            sum += d;
314	            doubleDigit = !doubleDigit;
315	        }
316	        return (10 - (sum % 10)) % 10;
317	    }
318	
319	    /**
320	     * The owner's age band, derived from its {@code birthDate} measured against its
321	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
322	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
323	     * over. The age is the number of whole years between the two dates. Returns
324	     * {@code null} when either date is absent, so no band is reported for an owner
325	     * without a supplied birth date.
326	     *
327	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
328	     */
329	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
330	        if (birthDate == null || registrationDate == null) {
331	            return null;
332	        }
333	        int age = Period.between(birthDate, registrationDate).getYears();
334	        if (age < 18) {
335	            return "MINOR";
336	        }
337	        if (age < 65) {
338	            return "ADULT";
339	        }
340	        return "SENIOR";
341	    }
342	
343	    /**
344	     * The single derived key used for duplicate detection, formed as
345	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
346	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
347	     * is the stored (lower-cased) email or the empty string when absent, and the
348	     * household component is the stored {@code householdId} or the empty string
349	     * when the owner belongs to no household.
350	     *
351	     * @return the owner's identity key
352	     */
353	    static String identityKey(String telephone, String email, String householdId) {
354	        String tel = telephone == null ? "" : telephone;
355	        String mail = email == null ? "" : email;
356	        String household = householdId == null ? "" : householdId;
357	        return tel + "|" + mail + "|" + household;
358	    }
359	
360	    /**
361	     * The owner's customer code, formatted {@code <REGION>-<HASH8>}: {@code region} is
362	     * the owner's canonical region (see {@link #region(String, String)}) and HASH8 is the
363	     * first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's
364	     * normalised telephone concatenated with its last name (e.g. {@code NSW-9F86D081}).
365	     *
366	     * @return the customer code
367	     */
368	    static String customerCode(String region, String telephone, String lastName) {
369	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
370	        return String.format("%s-%s", region, hash8);
371	    }
372	
373	    /**
374	     * The owner's membership number, formatted {@code <customerCode>-M<YY>}: the owner's
375	     * already-assigned {@code customerCode} followed by {@code -M} and the two-digit fiscal
376	     * year segment derived from its {@code registrationDate} (the last two digits of the
377	     * fiscal year that contains that date; see {@link #fiscalYearOf(LocalDate)}), e.g.
378	     * {@code NSW-9F86D081-M27} for a registration date of {@code 2026-08-03}. Derived from
379	     * the customer code and registration date once both have been assigned, so it lives with
380	     * the other owner derivations rather than in the controller that assigns it.
381	     *
382	     * @return the membership number
383	     */
384	    static String membershipNumber(String customerCode, LocalDate registrationDate) {
385	        int yy = fiscalYearOf(registrationDate) % 100;
386	        return String.format("%s-M%02d", customerCode, yy);
387	    }
388	
389	    /**
390	     * The stable identifier for the household an owner belongs to, derived
391	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
392	     * every owner sharing a last name and postcode resolves to the same value. It is the
393	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
394	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
395	     * empty string).
396	     *
397	     * @return the household identifier
398	     */
399	    static String householdId(String normalizedLastName, String postcode) {
400	        String pc = postcode == null ? "" : postcode;
401	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
402	    }
403	
404	    /**
405	     * Reduce an address to its canonical stored form: trim and collapse runs of
406	     * whitespace to a single space, upper-case, and expand common abbreviations
407	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
408	     * they appear as whole words. The result is what is stored, returned and used
409	     * for every household comparison; it is idempotent, so re-normalising an
410	     * already-normalised address leaves it unchanged.
411	     *
412	     * @param value the raw address (may be {@code null})
413	     * @return the normalised address, or the empty string if {@code value} is
414	     *         {@code null} or blank
415	     */
416	    static String normalizeAddress(String value) {
417	        String collapsed = collapseWhitespace(value).toUpperCase();
418	        if (collapsed.isEmpty()) {
419	            return "";
420	        }
421	        String[] tokens = collapsed.split(" ");
422	        for (int i = 0; i < tokens.length; i++) {
423	            tokens[i] = switch (tokens[i]) {
424	                case "ST" -> "STREET";
425	                case "RD" -> "ROAD";
426	                case "AVE" -> "AVENUE";
427	                default -> tokens[i];
428	            };
429	        }
430	        return String.join(" ", tokens);
431	    }
432	
433	    /**
434	     * Trim the given value and collapse every internal run of whitespace to a single
435	     * space, treating an absent value as empty. This is the single whitespace
436	     * normalisation the name and address normalisers share, so they agree on what
437	     * counts as insignificant whitespace; each then applies its own casing (and, for
438	     * addresses, whole-word abbreviation expansion).
439	     *
440	     * @param value the raw value (may be {@code null})
441	     * @return the trimmed, whitespace-collapsed value, or the empty string when
442	     *         {@code value} is {@code null}
443	     */
444	    static String collapseWhitespace(String value) {
445	        if (value == null) {
446	            return "";
447	        }
448	        return value.trim().replaceAll("\\s+", " ");
449	    }
450	
451	    /**
452	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
453	     * hexadecimal string. Callers take the prefix and case they need.
454	     */
455	    static String sha256Hex(String value) {
456	        try {
457	            byte[] digest = MessageDigest.getInstance("SHA-256")
458	                .digest(value.getBytes(StandardCharsets.UTF_8));
459	            StringBuilder hex = new StringBuilder(digest.length * 2);
460	            for (byte b : digest) {
461	                hex.append(String.format("%02x", b));
462	            }
463	            return hex.toString();
464	        } catch (NoSuchAlgorithmException e) {
465	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
466	        }
467	    }
468	}
