110	    /**
111	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that key
112	     * originally created, so a retried create with the same key returns that owner instead
113	     * of creating a duplicate. Held in memory for the application's lifetime and keyed by the
114	     * raw header value.
115	     */
116	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
121	        boolean hasKey = idempotencyKey != null && !idempotencyKey.isBlank();
122	        if (hasKey) {
123	            Integer existingId = idempotentCreates.get(idempotencyKey);
124	            if (existingId != null) {
125	                Owner existing = this.clinicService.findOwnerById(existingId);
126	                if (existing != null) {
127	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
128	                }
129	            }
130	        }
131	        ResponseEntity<OwnerDto> response = createNewOwner(ownerFieldsDto);
132	        if (hasKey && response.getStatusCode() == HttpStatus.CREATED
133	            && response.getBody() != null && response.getBody().getId() != null) {
134	            idempotentCreates.putIfAbsent(idempotencyKey, response.getBody().getId());
135	        }
136	        return response;
137	    }
